#include <bits/stdc++.h>
using namespace std;const int N=512,P=998244353,G=3,M=128,S=4096;static int a[N],b[N],c[N],d[N],r[N],j[N],v[N],t[S],y[S],u[4*M],z[4*M],x[M],o[M],w[M];static int e,k;
int pw(int a,int b=P-2){int s=1;for(;b;b>>=1,a=1LL*a*a%P)if(b&1)s=1LL*s*a%P;return s;}void f(int*a,int n,int q){for(int i=0;i<n;i++)if(i<r[i])swap(a[i],a[r[i]]);for(int l=2;l<=n;l<<=1){int w=pw(G,(P-1)/l);if(q<0)w=pw(w);for(int i=0;i<n;i+=l)for(int j=0,s=1;j<l/2;j++,s=1LL*s*w%P){int x=a[i+j],y=1LL*s*a[i+j+l/2]%P;a[i+j]=(x+y)%P;a[i+j+l/2]=(x-y+P)%P;}}if(q<0){int w=pw(n);for(int i=0;i<n;i++)a[i]=1LL*a[i]*w%P;}}void ml(const int*x,int n,const int*y,int m,int*o){int l=n+m-1;if(1LL*n*m<=64){memset(o,0,l*sizeof(int));for(int i=0;i<n;i++)for(int j=0;j<m;j++)o[i+j]=(o[i+j]+1LL*x[i]*y[j])%P;return;}int q=1,s=0;while(q<l)q<<=1,s++;memset(a,0,q*sizeof(int));memset(b,0,q*sizeof(int));memcpy(a,x,n*sizeof(int));memcpy(b,y,m*sizeof(int));r[0]=0;for(int i=1;i<q;i++)r[i]=(r[i>>1]>>1)|((i&1)<<(s-1));f(a,q,1);f(b,q,1);for(int i=0;i<q;i++)a[i]=1LL*a[i]*b[i]%P;f(a,q,-1);memcpy(o,a,l*sizeof(int));}void iv(const int*x,int n,int*y){memset(y,0,n*sizeof(int));y[0]=pw(x[0]);for(int k=1;k<n;k<<=1){int l=min(k<<1,n),q=1,s=0;while(q<l*2)q<<=1,s++;memset(a,0,q*sizeof(int));memset(b,0,q*sizeof(int));memcpy(a,x,l*sizeof(int));memcpy(b,y,k*sizeof(int));r[0]=0;for(int i=1;i<q;i++)r[i]=(r[i>>1]>>1)|((i&1)<<(s-1));f(a,q,1);f(b,q,1);for(int i=0;i<q;i++)b[i]=1LL*b[i]*(2-1LL*a[i]*b[i]%P+P)%P;f(b,q,-1);memcpy(y+k,b+k,(l-k)*sizeof(int));}}void md(const int*x,int n,const int*g,int m,int*o){if(n<m){memcpy(o,x,n*sizeof(int));memset(o+n,0,(m-1-n)*sizeof(int));return;}if(m<=8){memcpy(c,x,n*sizeof(int));for(int i=n-1;i>=m-1;i--)for(int j=0,s=c[i];j<m;j++)c[i-m+1+j]=(c[i-m+1+j]-1LL*s*g[j]%P+P)%P;memcpy(o,c,(m-1)*sizeof(int));return;}int q=n-m+1;memset(c,0,q*sizeof(int));for(int i=0;i<m&&i<q;i++)c[i]=g[m-1-i];iv(c,q,d);for(int i=0;i<q;i++)j[i]=x[n-1-i];ml(j,q,d,q,c);for(int i=0;i<q;i++)j[i]=c[q-1-i];ml(g,m,j,q,c);for(int i=0;i<m-1;i++)o[i]=(x[i]-c[i]+P)%P;}
void bd(int q,int l,int h){if(l==h){u[q]=e;z[q]=2;t[e++]=(P-x[l])%P;t[e++]=1;return;}int m=(l+h)>>1;bd(q<<1,l,m);bd(q<<1|1,m+1,h);u[q]=e;z[q]=z[q<<1]+z[q<<1|1]-1;ml(t+u[q<<1],z[q<<1],t+u[q<<1|1],z[q<<1|1],t+e);e+=z[q];}void ev(int q,int l,int h,const int*p,int n){if(l==h){o[l]=p[0];return;}int m=(l+h)>>1,L=z[q<<1]-1,R=z[q<<1|1]-1,s=k;k+=L;md(p,n,t+u[q<<1],z[q<<1],y+s);int h0=k;k+=R;md(p,n,t+u[q<<1|1],z[q<<1|1],y+h0);ev(q<<1,l,m,y+s,L);ev(q<<1|1,m+1,h,y+h0,R);}int main(int C,char**V){ios::sync_with_stdio(0);cin.tie(0);int R=C>1?stoi(V[1]):1000;unsigned long long s=C>2?stoull(V[2]):1;mt19937_64 g(s);while(R--){int n=g()%60+1,m=g()%60+1;e=k=0;for(int i=0;i<=n;i++)v[i]=g()%P;for(int i=0;i<m;i++)x[i]=g()%P;bd(1,0,m-1);if(n+1>=z[1]){k=m;md(v,n+1,t+u[1],z[1],y);ev(1,0,m-1,y,m);}else ev(1,0,m-1,v,n+1);for(int i=0;i<m;i++){int q=0;for(int j=n;j>=0;j--)q=(1LL*q*x[i]+v[j])%P;if(q!=o[i])return cout<<"WA\n",1;}}cout<<"OK\n";}
